Set-Location "C:\Users\maury\Documents\Murf Challenge\frontend"
$base = "http://localhost:3001"
$pages = @('/dashboard','/dashboard/catalogue','/dashboard/orders','/dashboard/live','/dashboard/agents','/dashboard/integrations','/dashboard/callers','/api/catalogue','/api/callers')
foreach ($p in $pages) {
  try { $r = Invoke-WebRequest -Uri "$base$p" -UseBasicParsing -TimeoutSec 30; Write-Output ("{0,-28} {1}" -f $p, $r.StatusCode) }
  catch { Write-Output ("{0,-28} ERR {1}" -f $p, $_.Exception.Message) }
}
